import { Leaf, Users, ShoppingBag, Truck, ChevronDown } from 'lucide-react';
import { ProduceCard } from '../features/produce/ProduceCard';

// Dummy data mirroring the image until we connect the backend API
const DUMMY_PRODUCE = [
  { _id: '1', cropType: 'Tomatoes', weightKg: 300, location: 'Nsawam, Eastern Region', pricePerKg: 4.00, status: 'Fresh' },
  { _id: '2', cropType: 'Plantain', weightKg: 500, location: 'Akim Oda, Eastern Region', pricePerKg: 3.50, status: 'Fresh' },
  { _id: '3', cropType: 'Maize', weightKg: 1000, location: 'Ejura, Ashanti Region', pricePerKg: 2.80, status: 'High Demand' },
  { _id: '4', cropType: 'Cassava', weightKg: 800, location: 'Techiman, Bono Region', pricePerKg: 2.00, status: 'Fresh' },
  { _id: '5', cropType: 'Pepper', weightKg: 150, location: 'Hohoe, Volta Region', pricePerKg: 6.00, status: 'Fresh' },
  { _id: '6', cropType: 'Ginger', weightKg: 200, location: 'Kumasi, Ashanti Region', pricePerKg: 8.00, status: 'Good Quality' },
];

const statCards = [
  { label: 'Total Produce Available', value: '1,256 kg', icon: Leaf, color: 'text-farmGreen', bg: 'bg-farmGreen-light' },
  { label: 'Active Farmers', value: '86', icon: Users, color: 'text-blue-600', bg: 'bg-blue-100' },
  { label: 'Registered Buyers', value: '42', icon: ShoppingBag, color: 'text-red-600', bg: 'bg-red-100' },
  { label: 'Ongoing Deliveries', value: '18', icon: Truck, color: 'text-teal-600', bg: 'bg-teal-100' },
];

export const Marketplace = () => {
  return (
    <div className="space-y-6">
      
      {/* 1. Statistics Row */}
      <section className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {statCards.map((stat, idx) => (
          <div key={idx} className="flex items-center p-4 bg-white rounded-xl border border-gray-200 shadow-sm">
            <div className={`p-3 rounded-xl ${stat.bg} ${stat.color} mr-4`}>
              <stat.icon size={24} />
            </div>
            <div>
              <h4 className="text-2xl font-extrabold text-gray-900">{stat.value}</h4>
              <p className="text-sm font-medium text-gray-500">{stat.label}</p>
            </div>
          </div>
        ))}
      </section>

      {/* 2. Promotional Banner */}
      <section className="relative overflow-hidden rounded-2xl bg-farmGreen shadow-sm">
        {/* Abstract background pattern/image would go here */}
        <div className="relative z-10 p-8 md:p-12 max-w-2xl text-white">
          <h2 className="text-3xl md:text-4xl font-extrabold mb-3">
            Fresh Produce<br />Stronger Communities
          </h2>
          <p className="text-lg text-green-50 mb-6 font-medium max-w-md">
            Connecting farmers to buyers — even in remote areas.
          </p>
          <button className="px-6 py-2.5 bg-white text-farmGreen rounded-lg font-bold hover:bg-gray-50 transition-colors flex items-center gap-2">
            Browse Produce <span aria-hidden="true">&rarr;</span>
          </button>
        </div>
      </section>

      {/* 3. Filter & Sort Bar */}
      <section className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex flex-col lg:flex-row lg:items-center justify-between gap-4">
        {/* Categories */}
        <div className="flex gap-2 overflow-x-auto pb-2 lg:pb-0 hide-scrollbar">
          {['All Produce', 'Fruits', 'Vegetables', 'Grains', 'Tubers', 'Others'].map((cat, idx) => (
            <button 
              key={cat} 
              className={`whitespace-nowrap px-4 py-2 rounded-full text-sm font-semibold transition-colors ${
                idx === 0 ? 'bg-farmGreen text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* Dropdowns */}
        <div className="flex flex-wrap items-center gap-3">
          {['Select Location', 'Crop Type', 'Quantity', 'Price Range', 'Sort By'].map((filter) => (
            <div key={filter} className="flex items-center gap-2 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 cursor-pointer hover:bg-gray-50">
              <span className="font-medium">{filter}</span>
              <ChevronDown size={14} />
            </div>
          ))}
        </div>
      </section>

      {/* 4. Produce Grid */}
      <section className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 pb-8">
        {DUMMY_PRODUCE.map((item) => (
          <ProduceCard key={item._id} item={item} />
        ))}
      </section>

    </div>
  );
};
